const actions = {inspect_tab:'terminal.inspect',insert_in_tab:'terminal.insert',clear_tab_input:'terminal.clear',replace_tab_input:'terminal.replace',append_to_tab_input:'terminal.append',clear_input:'computer.clear',replace_input:'computer.replace',send_to_tab:'terminal.send',queue_in_tab:'terminal.queue',focus_tab:'terminal.focus',move_tab:'terminal.move',close_tab:'terminal.close',resolve_close:'terminal.close.resolve'};
Object.assign(actions,{list_terminal_workspace_windows:'mainworkspace.windows',inspect_terminal_workspace_window:'mainworkspace.preview',inspect_terminal_window_close:'mainworkspace.close.inspect',close_terminal_window:'mainworkspace.close',save_main_terminal_workspace:'mainworkspace.save',restore_main_terminal_workspace:'mainworkspace.restore',remove_main_workspace_project:'mainworkspace.remove',recover_main_workspace_snapshot:'mainworkspace.recover',new_terminal_tab:'terminal.new',inspect_terminal_input:'terminal.native.inspect',type_terminal_input:'terminal.native.type',press_terminal_key:'terminal.key',queue_tab_draft:'terminal.queue',attach_images_in_tab:'terminal.images',clipboard:'remote.clipboard',terminal_pointer:'terminal.pointer'});
